/* From Uiverse.io by guilhermeyohan - Tags: form */
.__UIV_SCOPE__ .container {
  max-width: 300px;
  margin: 0 auto;
  padding: 20px;
  background-color: #13121269;
  border-radius: 5px;
}

.__UIV_SCOPE__ label {
  font-weight: bold;
  display: block;
  margin-bottom: 10px;
}

.__UIV_SCOPE__ .inpdddut[type="file"] {
  padding: 10px;
  margin-bottom: 20px;
  border: none;
  background-color: #1aa3bb;
  border-radius: 5px;
  width: 100%;
  cursor: pointer;
}

.__UIV_SCOPE__ .inpdddut[type="submit"] {
  padding: 10px 20px;
  background-color: #008CBA;
  color: #fff;
  border: none;
  border-radius: 5px;
  cursor: pointer;
}

.__UIV_SCOPE__ .inpdddut[type="submit"]:hover {
  background-color: #006F8F;
}
